import * as z from 'zod';

/** All entity ids are UUIDs (v7, generated by the server). */
export const idSchema = z.uuid();
export type Id = z.infer<typeof idSchema>;

/** Calendar date without time, e.g. `2026-12-24`. */
export const isoDateSchema = z.iso.date();

/** Point in time with offset, e.g. `2026-11-15T18:30:00Z`. */
export const isoDateTimeSchema = z.iso.datetime({ offset: true });

/** Path parameter holding a single id, e.g. `{ scoreId }`. */
export const idParam = <K extends string>(key: K) => z.object({ [key]: idSchema } as { [P in K]: typeof idSchema });

/**
 * Query parameter that may occur repeatedly (`?voiceId=a&voiceId=b`).
 * Express delivers a single value as string and repeated values as array.
 */
export const queryArray = <T extends z.ZodType>(item: T, max = 200) =>
  z.preprocess(
    (v) => (v === undefined || v === '' ? [] : Array.isArray(v) ? v : [v]),
    z.array(item).max(max),
  );

/** Boolean query parameter (`true` / `false`). */
export const queryBoolean = z
  .enum(['true', 'false'])
  .transform((v) => v === 'true');

/** Response of every `…/create` action (201). */
export const createdResponseSchema = z.object({ id: idSchema });
export type CreatedResponse = z.infer<typeof createdResponseSchema>;

/** Names of tags, folders, ensembles, roles, voices … */
export const SHORT_NAME_MAX = 100;
export const shortNameSchema = z.string().trim().min(1).max(SHORT_NAME_MAX);

/** Body of every `…/rename` action. */
export const renameBodySchema = z.object({ name: shortNameSchema });
export type RenameBody = z.infer<typeof renameBodySchema>;

/** Short display reference to another entity. */
export const refSchema = z.object({ id: idSchema, name: z.string() });
export type Ref = z.infer<typeof refSchema>;
